-- BASELINE: the schema already applied to the production Supabase project
-- (copied unchanged from the original schema.sql). Do not edit this file;
-- change the schema with a new, later-timestamped migration instead.

-- Run this once in the Supabase SQL editor (Project -> SQL Editor -> New query).
-- Creates the saved_jobs table and locks it down with Row Level Security so
-- each signed-in user can only ever read/write their own rows.

create table if not exists public.saved_jobs (
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  job_id text not null,
  title text,
  company text,
  location text,
  job_url text,
  job_type text,
  site text,
  date_posted text,
  description text,
  saved_at timestamptz not null default now(),
  primary key (user_id, job_id)
);

alter table public.saved_jobs enable row level security;

create policy "Users can view their own saved jobs"
  on public.saved_jobs for select
  using (auth.uid() = user_id);

create policy "Users can insert their own saved jobs"
  on public.saved_jobs for insert
  with check (auth.uid() = user_id);

create policy "Users can update their own saved jobs"
  on public.saved_jobs for update
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

create policy "Users can delete their own saved jobs"
  on public.saved_jobs for delete
  using (auth.uid() = user_id);

-- ---------------------------------------------------------------------------
-- Private per-user search runs. Each "Run New Search" click creates one row
-- here; the GitHub Actions workflow writes that run's results into
-- search_results (using the service role key, which bypasses RLS) instead of
-- the one shared docs/data/jobs.json — so one user's search never overwrites
-- or leaks into another user's results.

create table if not exists public.search_runs (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  search_term text,
  location text,
  params jsonb not null default '{}'::jsonb,
  status text not null default 'pending', -- pending | running | completed | failed
  error text,
  created_at timestamptz not null default now(),
  completed_at timestamptz
);

alter table public.search_runs enable row level security;

create policy "Users can view their own search runs"
  on public.search_runs for select
  using (auth.uid() = user_id);

create policy "Users can create their own search runs"
  on public.search_runs for insert
  with check (auth.uid() = user_id);

-- No update/delete policy for regular users: only the GitHub Actions workflow
-- (via the service role key, which ignores RLS entirely) transitions a run's
-- status to running/completed/failed.

create table if not exists public.search_results (
  run_id uuid not null references public.search_runs(id) on delete cascade,
  job_id text not null,
  title text,
  company text,
  location text,
  job_url text,
  job_type text,
  site text,
  date_posted text,
  description text,
  primary key (run_id, job_id)
);

alter table public.search_results enable row level security;

create policy "Users can view results of their own search runs"
  on public.search_results for select
  using (exists (
    select 1 from public.search_runs r
    where r.id = search_results.run_id and r.user_id = auth.uid()
  ));

-- No insert/update/delete policy for regular users: results are written only
-- by the GitHub Actions workflow via the service role key.

-- ---------------------------------------------------------------------------
-- Lets the frontend resolve "username" -> the account's current login email
-- at sign-in time, without exposing auth.users directly. Every account has a
-- real, Supabase-confirmed email from sign-up (see docs/assets/app.js
-- signUp()); if the user later changes it via updateContactEmail(), this
-- function transparently starts returning the new one, so login-by-username
-- keeps working across an email change.

create or replace function public.get_login_email(p_username text)
returns text
language sql
security definer
set search_path = public
as $$
  select email from auth.users
  where lower(raw_user_meta_data->>'username') = lower(p_username)
  limit 1;
$$;

revoke all on function public.get_login_email(text) from public;
grant execute on function public.get_login_email(text) to anon, authenticated;

-- ---------------------------------------------------------------------------
-- Recurring (daily/weekly) per-user scrapes. Entirely separate from
-- saved_jobs and from the one-off search_runs/search_results pair above —
-- a schedule here is a standing request ("keep searching for X every day
-- for me"), not a single manual run, and its results live in their own
-- table (scheduled_search_results) so they never mix with a user's
-- manually saved jobs list.
--
-- Users manage their own schedules directly (create/pause/edit/delete);
-- scraper/run_scheduled_searches.py (run hourly by
-- .github/workflows/scheduled-scrapes.yml, via the service role key) is the
-- only writer of last_run_at/next_run_at/last_status/last_error.

create table if not exists public.scheduled_searches (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  frequency text not null default 'daily', -- 'daily' | 'weekly'
  search_term text,
  location text,
  params jsonb not null default '{}'::jsonb,
  is_active boolean not null default true,
  last_status text, -- null | running | completed | failed
  last_error text,
  last_run_at timestamptz,
  next_run_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  constraint scheduled_searches_frequency_check check (frequency in ('daily', 'weekly'))
);

alter table public.scheduled_searches enable row level security;

create policy "Users can view their own scheduled searches"
  on public.scheduled_searches for select
  using (auth.uid() = user_id);

create policy "Users can create their own scheduled searches"
  on public.scheduled_searches for insert
  with check (auth.uid() = user_id);

create policy "Users can update their own scheduled searches"
  on public.scheduled_searches for update
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

create policy "Users can delete their own scheduled searches"
  on public.scheduled_searches for delete
  using (auth.uid() = user_id);

create table if not exists public.scheduled_search_results (
  id uuid primary key default gen_random_uuid(),
  schedule_id uuid not null references public.scheduled_searches(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  run_at timestamptz not null default now(),
  job_id text not null,
  title text,
  company text,
  location text,
  job_url text,
  job_type text,
  site text,
  date_posted text,
  description text,
  unique (schedule_id, run_at, job_id)
);

alter table public.scheduled_search_results enable row level security;

create policy "Users can view their own scheduled search results"
  on public.scheduled_search_results for select
  using (auth.uid() = user_id);

create policy "Users can delete their own scheduled search results"
  on public.scheduled_search_results for delete
  using (auth.uid() = user_id);

-- No insert/update policy for regular users: results are written only by
-- scraper/run_scheduled_searches.py via the service role key.
